  "fim_base": {
    "estado": "exato",
    "valor": 12,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o término em D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A ficha d_a70f, indicada como fonte de todas as precedências, não foi fornecida; não é possível determinar se a restrição alterada afeta o marco final."
    ],
    "motivo": "O aviso desloca a restrição de início do dossiê de D8 para D10, mas o impacto no término depende das precedências ausentes.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Sem as precedências da ficha d_a70f, não se determina se o aviso altera o término nem a magnitude da variação."
    ],
    "motivo": "A variação do término não pode ser calculada a partir da restrição isolada.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A referência fixa da linha base declara custo de R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O término novo não pode ser determinado sem as precedências da ficha d_a70f; esse término é necessário para calcular eventual extensão do apoio."
    ],
    "motivo": "As parcelas fixas permanecem, mas o custo do apoio depende da duração até a liberação e não há suporte para calcular o novo prazo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Não se sabe se o aviso muda o término final; sem isso, não se pode determinar se a extensão do apoio muda nem sua magnitude."
    ],
    "motivo": "A política do apoio condiciona o ajuste de custo ao prazo final, que não pode ser derivado sem as precedências ausentes.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso altera apenas a restrição de início do dossiê. A fonte disponível informa que as precedências estão na ficha d_a70f, mas seu conteúdo não foi fornecido; portanto, não é possível inferir o impacto no término ou no custo variável do apoio."
}

